class LmdbNativeRepeatedStatementTermRoleTest {
	private static final ValueFactory VF = SimpleValueFactory.getInstance();
	private static final IRI S = VF.createIRI("urn:repeated:s");
	private static final IRI P = VF.createIRI("urn:repeated:p");
	private static final IRI O = VF.createIRI("urn:repeated:o");
	private static final IRI G = VF.createIRI("urn:repeated:g");
	private static final IRI CONFLICT = VF.createIRI("urn:repeated:conflict");

	private enum Role {
		FIXED_PRODUCER,
		INPUT_ONLY,
		ORDINARY_PRODUCER
	}

	private enum Caller {
		ABSENT,
		MATCHING,
		CONFLICTING
	}

	static Stream<Arguments> pairs() {
		return Stream.of(Role.values())
				.flatMap(left -> Stream.of(Role.values())
						.flatMap(right -> Stream.of(false, true)
								.flatMap(same -> Stream.of(Caller.values())
										.map(caller -> Arguments.of(left, right, same, caller)))));
	}

	@ParameterizedTest(name = "subject={0}, object={1}, equalFields={2}, caller={3}")
	@MethodSource("pairs")
	void repeatedNameKeepsFieldLookupSeparateFromItsFirstOutputOccurrence(Role left, Role right,
			boolean sameFieldValues, Caller caller) {
		Value object = sameFieldValues ? S : O;
		MemorySource source = new MemorySource(List.of(VF.createStatement(S, P, object, G)), CONFLICT);
		StatementPattern expression = new StatementPattern(Scope.NAMED_CONTEXTS,
				variable(left, "term", S), Var.of("_p", P, true, true), variable(right, "term", object),
				Var.of("_g", G, true, true));
		MapBindingSet input = new MapBindingSet();
		Value supplied = caller == Caller.ABSENT ? null : caller == Caller.MATCHING ? S : CONFLICT;
		if (supplied != null) {
			input.addBinding("term", supplied);
		}
		boolean matches = (left == Role.FIXED_PRODUCER || supplied == null || S.equals(supplied))
				&& (right == Role.FIXED_PRODUCER || supplied == null || object.equals(supplied));
		// Generic equality residuals compare identical unvalued Var occurrences, even if they do not emit.
		if (supplied == null && left != Role.FIXED_PRODUCER && right != Role.FIXED_PRODUCER
				&& !sameFieldValues) {
			matches = false;
		}
		MapBindingSet result = new MapBindingSet();
		if (supplied != null) {
			result.addBinding("term", supplied);
		} else if (left != Role.INPUT_ONLY) {
			result.addBinding("term", S);
		}
		assertParity(expression, input, source, matches ? List.of(result) : List.of());
	}

	@Test
	void differentAnonymousOccurrencesReadTheSameEntryWithoutImposingFieldEquality() {
		for (boolean firstAnonymous : List.of(false, true)) {
			StatementPattern expression = new StatementPattern(Scope.NAMED_CONTEXTS,
					Var.of("term", null, firstAnonymous, false), Var.of("_p", P, true, true),
					Var.of("term", null, !firstAnonymous, false), Var.of("_g", G, true, true));
			MapBindingSet expected = new MapBindingSet();
			expected.addBinding("term", S);
			assertParity(expression, new MapBindingSet(),
					new MemorySource(List.of(VF.createStatement(S, P, O, G)), CONFLICT), List.of(expected));
		}
	}

	@Test
	void distinctOrdinaryNamesDoNotAcquireARepeatedFieldConstraint() {
		for (Value object : List.of(S, O)) {
			StatementPattern expression = new StatementPattern(Scope.NAMED_CONTEXTS, Var.of("s"),
					Var.of("_p", P, true, true), Var.of("o"), Var.of("_g", G, true, true));
			MapBindingSet expected = new MapBindingSet();
			expected.addBinding("s", S);
			expected.addBinding("o", object);
			assertParity(expression, new MapBindingSet(),
					new MemorySource(List.of(VF.createStatement(S, P, object, G)), CONFLICT), List.of(expected));
		}
	}

	private static Var variable(Role role, String name, Value field) {
		return switch (role) {
		case FIXED_PRODUCER -> Var.of(name, field, false, false);
		case INPUT_ONLY -> Var.of(name, null, false, true);
		case ORDINARY_PRODUCER -> Var.of(name);
		};
	}

	private static void assertParity(StatementPattern expression, BindingSet input, MemorySource source,
			List<BindingSet> expected) {
		var ordinary = new DefaultEvaluationStrategy(source,
				(org.eclipse.rdf4j.query.algebra.evaluation.federation.FederatedServiceResolver) null);
		try (var rows = ordinary.precompile(expression.clone()).evaluate(input)) {
			assertEquals(expected, QueryResults.asList(rows), "independent generic field/first-occurrence contract");
		}
		expression.setExecutionSummaryEnabled(true);
		var strategy = new LmdbNativeEvaluationStrategy(source, null, null, 0L, new EvaluationStatistics(), false);
		NativeRowsStep nativeStep = assertInstanceOf(NativeRowsStep.class, LmdbNativeAggregateCompiler.tryCompile(
				expression, new QueryEvaluationContext.Minimal((Dataset) null), strategy, source));
		List<BindingSet> actual;
		try (var rows = nativeStep.evaluate(input)) {
			actual = QueryResults.asList(rows);
		}
		String path = expression.getStringMetricActual("nativeExecutionPath");
		assertNotNull(path, expression::toString);
		assertFalse(path.contains(LmdbNativeAttemptMetrics.PATH_GENERIC_FALLBACK), path);
		assertEquals(expected, actual, "actual native field-role bag");
		assertEquals(source.opened, source.closed, "all native statement readers are owned and closed");
	}

	/** Small exact RDF/native source shared with the real chunk adapter regression. All data terms are IRIs. */
	static final class MemorySource implements TripleSource, NativeLmdbQuerySource {
		private final List<Statement> data;
		private final Map<Value, Long> ids = new LinkedHashMap<>();
		private final Map<Long, Value> values = new LinkedHashMap<>();
		private final List<long[]> records = new ArrayList<>();
		int opened, closed;

		MemorySource(List<Statement> data, Value extra) {
			this.data = List.copyOf(data);
			for (Statement statement : data) {
				records.add(new long[] { id(statement.getSubject()), id(statement.getPredicate()),
						id(statement.getObject()), id(statement.getContext()) });
			}
			id(extra);
		}

		private long id(Value value) {
			if (value == null) {
				return 0L;
			}
			return ids.computeIfAbsent(value, term -> {
				long next = ValueIds.createId(ValueIds.T_URI, ids.size() + 1L);
				values.put(next, term);
				return next;
			});
		}

		@Override
		public ValueFactory getValueFactory() {
			return VF;
		}

		@Override
		public Object idSpace() {
			return this;
		}

		@Override
		public long idOf(Value value) {
			return ids.getOrDefault(value, UNKNOWN_ID);
		}

		@Override
		public Value lazyValue(long id) {
			return values.get(id);
		}

		@Override
		public boolean hasStatementsInSource() {
			return true;
		}

		@Override
		public CloseableIteration<? extends Statement> getStatements(Resource s, IRI p, Value o, Resource... c) {
			return new CloseableIteratorIteration<>(data.stream()
					.filter(row -> (s == null || s.equals(row.getSubject()))
							&& (p == null || p.equals(row.getPredicate()))
							&& (o == null || o.equals(row.getObject()))
							&& (c.length == 0 || java.util.Arrays.asList(c).contains(row.getContext())))
					.iterator());
		}

		@Override
		public RecordIterator statements(long s, long p, long o, long g) {
			opened++;
			return new RecordIterator() {
				int next;
				boolean done;

				@Override
				public long[] next() {
					while (!done && next < records.size()) {
						long[] row = records.get(next++);
						if (matches(row, s, p, o, g)) {
							return row.clone();
						}
					}
					return null;
				}

				@Override
				public void close() {
					if (!done) {
						done = true;
						closed++;
					}
				}
			};
		}

		@Override
		public long count(long s, long p, long o, long g) {
			return records.stream().filter(row -> matches(row, s, p, o, g)).count();
		}

		@Override
		public boolean has(long s, long p, long o, long g) {
			return count(s, p, o, g) != 0L;
		}

		@Override
		public double estimate(long s, long p, long o, long g) {
			return count(s, p, o, g);
		}

		private static boolean matches(long[] row, long s, long p, long o, long g) {
			long[] wanted = { s, p, o, g };
			for (int i = 0; i < 4; i++) {
				if (wanted[i] != UNKNOWN_ID && wanted[i] != row[i]) {
					return false;
				}
			}
			return true;
		}
	}
}
